```
nudro mulBig(a, b) {
    # result length dra(a)+dra(b), init zeros
    plulai res := [];
    shoyo i := 0 busale dra(a) + dra(b) - 1
        sutse(res, 0);
    pla i
    plulai i := dra(a) - 1;
    plulai pos := dra(res) - 1;
    edrushe i >= 0
        plulai j := dra(b) - 1;
        plulai p := pos;
        edrushe j >= 0
            res[p] := res[p] + a[i] * b[j];
            p := p - 1;
            j := j - 1;
        aitudre
        i := i - 1;
        pos := pos - 1;
    aitudre
    # now normalize carries from the end
    plulai k := dra(res) - 1;
    edrushe k > 0
        res[k - 1] := res[k - 1] + res[k] / 10;
        res[k] := res[k] % 10;
        k := k - 1;
    aitudre
    druna res;
}
```
